import{_ as a,o,c as r,a2 as l}from"./chunks/framework.CqpfiAoK.js";const d=JSON.parse('{"title":"篇869｜超脱者与社会·超脱者与平民的关系","description":"","frontmatter":{"title":"篇869｜超脱者与社会·超脱者与平民的关系","no":869,"module":4,"tags":["超脱","社会","平民","万族有路","反掠夺"],"related":["08-人人有路保障体系","36-社会结构与阶层流动","51-人族定位与特质","781-超脱者的教育责任"]},"headers":[],"relativePath":"zh/869_模块4-超脱者与社会-超脱者与平民的关系.md","filePath":"zh/869_模块4-超脱者与社会-超脱者与平民的关系.md"}'),e={name:"zh/869_模块4-超脱者与社会-超脱者与平民的关系.md"};function i(n,t,s,h,u,_){return o(),r("div",null,[...t[0]||(t[0]=[l('<h1 id="篇869-超脱者与社会·超脱者与平民的关系" tabindex="-1">篇869｜超脱者与社会·超脱者与平民的关系 <a class="header-anchor" href="#篇869-超脱者与社会·超脱者与平民的关系" aria-label="Permalink to &quot;篇869｜超脱者与社会·超脱者与平民的关系&quot;">​</a></h1><blockquote><p>所属模块：模块四·超脱正统定义库｜对标地基：文档08、36、51、781</p></blockquote><h2 id="引言-超脱者不踩在平民头上-也不悬浮在云端" tabindex="-1">引言：超脱者不踩在平民头上，也不悬浮在云端 <a class="header-anchor" href="#引言-超脱者不踩在平民头上-也不悬浮在云端" aria-label="Permalink to &quot;引言：超脱者不踩在平民头上，也不悬浮在云端&quot;">​</a></h2><p>旧世界的超脱者与平民之间隔着一道天堑：平民仰望大帝如仰望星空，大帝俯视平民如俯视蝼蚁。两者之间没有真实关系——只有朝拜与被朝拜。衡元宙必须回答：<strong>超脱者和万族中那些刚刚感元境甚至还没开始修炼的平民，究竟应该是什么关系？</strong> 本篇把这条关系钉死。</p><p>六大顶层公理在此刻同时压阵：反掠夺主义公理禁止超脱者把平民当修炼资源；万族共和公理确认平民与超脱者拥有平等的进化资格；集体升维公理要求超脱者把平民带进门而不是把平民踩在脚下；因果自律公理要求超脱者与平民的互动全程留痕、不扰动平民因果；法则优先公理要求这条关系法则级自洽，不因剧情需要而随意设定&quot;大帝微服私访&quot;式的浪漫化叙事；众生全员无限均等公理确认所有生灵自带基础无限之力，佛系懒狗保有保底不被淘汰，卷王少年至尊可叠加更高无限——无限本源人人自带，掠夺自然失去意义。</p><p>众生全员无限均等法则：锚点共生文明内，所有生灵自带基础无限之力；佛系/懒狗保有保底基础无限，不会被时代淘汰；卷王、少年至尊可叠加更多更高层级的无限。无限本源人人自带，掠夺自然失去意义。</p><h2 id="一、关系底线-平民不是修炼资源" tabindex="-1">一、关系底线：平民不是修炼资源 <a class="header-anchor" href="#一、关系底线-平民不是修炼资源" aria-label="Permalink to &quot;一、关系底线：平民不是修炼资源&quot;">​</a></h2><p>旧世界最常见的掠夺逻辑就是把平民当资源——血食、鼎炉、药引、人牲。衡元宙用最严厉的法则封死这条路径：</p><ul><li>平民的生命、能量、意识，神圣不可侵犯</li><li>超脱者若以任何形式抽取平民本源，触发阿赖耶网络+多层监督的最高级警报</li><li>违规者不仅剥夺超脱者资格，还须通过共生法院审判</li></ul><p>这条底线不是道德说教，是反掠夺主义公理的硬执行。它意味着：<strong>超脱者与平民之间，不存在&quot;强者吃弱者&quot;的食物链。</strong> 平民不是超脱者的养料，而是超脱者服务的对象。</p><h2 id="二、关系正线-超脱者是平民进化的引路人" tabindex="-1">二、关系正线：超脱者是平民进化的引路人 <a class="header-anchor" href="#二、关系正线-超脱者是平民进化的引路人" aria-label="Permalink to &quot;二、关系正线：超脱者是平民进化的引路人&quot;">​</a></h2><p>底线之上，超脱者与平民的正向关系是什么？不是庇护（那是主宰者逻辑），而是引路：</p><ol><li><strong>开门</strong>：通过人人有路保障体系（文档08），确保每个平民都能找到适合自己的修炼路径，不会因为出身、种族、性别被挡在门外</li><li><strong>铺路</strong>：通过公共修炼场所、免费教材、公共算力，降低平民起步成本</li><li><strong>带路</strong>：超脱者培训与传承岗（篇720）定期下沉到平民社区，做启蒙授课、路径评估、误区纠正</li><li><strong>护门</strong>：防止掠夺派在平民中发展信徒——平民最容易被&quot;速成&quot;诱惑，超脱者有义务提供更好的正路选择</li></ol><p>引路关系的核心是：超脱者不替平民走路，但他必须确保门是开的、路是平的、灯是亮的。平民走多远，靠他自己；但门不能关，路不能堵。</p><h2 id="三、关系中的距离感" tabindex="-1">三、关系中的距离感 <a class="header-anchor" href="#三、关系中的距离感" aria-label="Permalink to &quot;三、关系中的距离感&quot;">​</a></h2><p>超脱者与平民之间需要保持健康的距离。太近不行——超脱者直接插手平民的日常事务，会变成干预内政；太远也不行——飘在云端不管平民死活，就是挂机养老。</p><p>衡元宙用制度调节这个距离：</p><ul><li><strong>法定互动渠道</strong>：平民通过万族代表、监督委员会、阿赖耶反馈系统与超脱者沟通，不搞&quot;拦驾告状&quot;</li><li><strong>定期下沉</strong>：超脱者每年必须完成一定时长的基层授课，不能只待在法则网络顶层</li><li><strong>禁止私交</strong>：超脱者不得与特定平民建立&quot;私人恩怨&quot;——你帮了张三，就要对李四也公平；帮一个人不叫服务万族</li><li><strong>禁止身份碾压</strong>：超脱者在公共场合不得以力量压制平民，不得以&quot;我是超脱者&quot;为由享有特殊待遇</li></ul><h2 id="四、平民对超脱者的权利" tabindex="-1">四、平民对超脱者的权利 <a class="header-anchor" href="#四、平民对超脱者的权利" aria-label="Permalink to &quot;四、平民对超脱者的权利&quot;">​</a></h2><p>关系是双向的。平民对超脱者拥有以下权利：</p><ul><li><strong>知情权</strong>：超脱者的岗位目标、资源使用、考核结果向平民公开</li><li><strong>监督权</strong>：平民发现超脱者违规，可通过阿赖耶网络+多层监督系统举报</li><li><strong>请求权</strong>：平民可以通过万族代表向超脱者提出合理的服务请求（如某区域法则网络维护需求）</li><li><strong>拒绝权</strong>：平民有权拒绝超脱者&quot;好心办坏事&quot;式的干预——如果你不需要超脱者帮忙，他不能硬帮</li></ul><p>这些权利确保平民不是被动接受庇护的对象，而是有主体性的公民。</p><h2 id="五、五大核心落点" tabindex="-1">五、五大核心落点 <a class="header-anchor" href="#五、五大核心落点" aria-label="Permalink to &quot;五、五大核心落点&quot;">​</a></h2><ul><li><strong>反能级浪费</strong>：超脱者不把平民当养料，平民也不把超脱者当神——双方的能量都用在共建上</li><li><strong>反掠夺</strong>：平民不是修炼资源，这条底线直接切断掠夺派最依赖的食物链</li><li><strong>唐罗上限对比</strong>：唐罗体系里平民是大帝的背景板，生死不由己；衡元宙里平民有完整权利，超脱者是其服务者</li><li><strong>万族全覆盖</strong>：平民涵盖万族五大谱系一切未入修炼门者，不分种族性别</li><li><strong>超多元全开放</strong>：公共教材、修炼场所、投诉渠道全部通过无私道全网开放</li></ul><h2 id="结论" tabindex="-1">结论 <a class="header-anchor" href="#结论" aria-label="Permalink to &quot;结论&quot;">​</a></h2><p>超脱者与平民的关系，不是主宰与蝼蚁，不是神与信徒，而是引路人与走路人。超脱者把门打开、把路铺平、把灯点亮；平民自己选择走不走、走多远。他不踩你，也不替你走——他只是确保门永远开着。这，才是超脱者与平民关系的正统定义。</p><h2 id="关联" tabindex="-1">关联 <a class="header-anchor" href="#关联" aria-label="Permalink to &quot;关联&quot;">​</a></h2><ul><li>关联文档：<a href="./08-人人有路保障体系.html">08-人人有路保障体系</a> · <a href="./36-社会结构与阶层流动.html">36-社会结构与阶层流动</a> · <a href="./51-人族定位与特质.html">51-人族定位与特质</a> · <a href="./781_模块4-万族-超脱者的教育责任.html">781-超脱者的教育责任</a></li><li>官网：<a href="https://faker210.github.io/hengyuan-cosmos/zh/" target="_blank" rel="noreferrer">https://faker210.github.io/hengyuan-cosmos/zh/</a></li></ul>',28)])])}const p=a(e,[["render",i]]);export{d as __pageData,p as default};
